pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IERC165Like {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

interface IAccessControlLike {
    function hasRole(bytes32 role, address account) external view returns (bool);
    function getRoleAdmin(bytes32 role) external view returns (bytes32);
    function grantRole(bytes32 role, address account) external;
    function revokeRole(bytes32 role, address account) external;
    function renounceRole(bytes32 role, address account) external;
}

contract InvMutTest is Test {
    C c;
    bytes4 constant ERC165_ID = type(IERC165Like).interfaceId;
    bytes4 constant ACCESS_CONTROL_ID = type(IAccessControlLike).interfaceId;

    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 id) public {
        // General rule: c reports support exactly for the ERC165 and IAccessControl interfaceIds,
        // and no other id. The mutant only reports IAccessControl.
        assertTrue(c.supportsInterface(id) == (id == ERC165_ID || id == ACCESS_CONTROL_ID));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 selectorKind, bytes4 extraSelector) public {
        // The whole bytes4 domain is admissible; we parameterize it so the fuzzer
        // covers all equivalence classes: ERC165 id, IAccessControl id, and arbitrary ids.
        selectorKind = bound(selectorKind, 0, 2);
        bytes4 id;
        if (selectorKind == 0) {
            id = type(IERC165).interfaceId;
        } else if (selectorKind == 1) {
            id = type(IAccessControl).interfaceId;
        } else {
            id = extraSelector;
        }

        bool supported = c.supportsInterface(id);
        bool ierc165 = c.supportsInterface(type(IERC165).interfaceId);
        bool iac = c.supportsInterface(type(IAccessControl).interfaceId);

        // General rule: support is reported exactly for IERC165 and IAccessControl,
        // and support of any id matches that membership.
        assertTrue(
            supported == (id == type(IERC165).interfaceId || id == type(IAccessControl).interfaceId)
                && ierc165 && iac
        );
    }
}
interface IERC165 { function supportsInterface(bytes4 interfaceId) external view returns (bool); }
interface IAccessControl { function hasRole(bytes32 role, address account) external view returns (bool); }

